        if cur_dir == '':
            cur_dir, cur_len = m, 1
        elif m == cur_dir:
            cur_len += 1
        else:
            if cur_len > best_len:
                best_dir, best_len = cur_dir, cur_len
            cur_dir, cur_len = m, 1
    if cur_len > best_len:
        best_dir, best_len = cur_dir, cur_len
    return (best_dir, best_len)
