def times_to_hundredths(times):
    result = []
    for t in times:
        try:
            m, rest = t.split(':')
            s, hh = rest.split('.')
            m, s, hh = int(m), int(s), int(hh)
            if m < 0 or s < 0 or hh < 0 or s > 59 or hh > 99:
                continue
            result.append(m * 6000 + s * 100 + hh)
        except ValueError:
            continue
    return result
